import sys

def is_palindrome(s):
    return s == s[::-1]

def count_palindromic_cyclic_shifts(S):
    n = len(S)
    count = 0
    for k in range(n):
        if is_palindrome(S[k:] + S[:k]):
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    index = 1
    for _ in range(T):
        S = input[index]
        results.append(count_palindromic_cyclic_shifts(S))
        index += 1
    for result in results:
        print(result)

main()
